const HX_POI_CAT={Settlements:'town',Fortifications:'castle',Sacred:'shrine',Dungeons:'cave',Infrastructure:'bridge',Resources:'gem-deposit',
  Special:'sanctum',Wilds:'thicket',Underdark:'cave'};
const HX_POI_TIER={city:1.4,castle:1.4,temple:1.4,fortress:1.4,hamlet:.7,outpost:.7,farm:.7,camp:.7,quarry:.7,ruins:.7,tomb:.7,labyrinth:.7,graveyard:.7};
// other tools' or renamed types: guess an icon from the name, else a plain monument stone
const HX_POI_GUESS=[[/city|town|village|hamlet|settle|inn|farm|camp|port|market/,'town'],[/castle|keep|fort|tower|wall|garrison/,'castle'],
  [/dungeon|cave|mine|lair|crypt|tomb|entrance|portal|ruin/,'cave'],[/shrine|temple|altar|grave|stone|sacred/,'shrine']];
const hxPoiIcon=t=>HX_ICONS[t]||HX_ICONS[HX_POI_CAT[HX_POI[t]?.[0]]]||HX_ICONS[(HX_POI_GUESS.find(([re])=>re.test(t))||[0,'monument'])[1]];
// Hexer brightens dark place colours so the badge never turns black: the brightest channel is lifted to at least 140
const hxPoiCol=t=>{const n=parseInt((HX_POI[t]?.[1]||'#b0a890').slice(1),16),c=[n>>16&255,n>>8&255,n&255],m=Math.max(...c,1);
  return '#'+(m<140?c.map(v=>Math.min(255,Math.round(v*140/m))):c).map(v=>v.toString(16).padStart(2,'0')).join('')};
